99	fn compile_impl<T: Output>(
100	    world: Tracked<dyn World + '_>,
101	    traced: Tracked<Traced>,
102	    sink: &mut Sink,
103	) -> SourceResult<T> {
104	    let library = world.library();
105	    match T::target() {
